css:
body { color:#171717; background:white; font-size:10.2pt; line-height:1.43; }
* { box-sizing:border-box; }
h1,h2,h3,p,ul,table { margin:0; }
a { color:inherit; text-decoration:none; }
strong { font-weight:700; }
p { margin:4pt 0; }
ul { padding-left:13pt; margin:4pt 0 7pt; }
li { margin:2pt 0; }
h2 { font-size:12pt; line-height:1.3; margin:14pt 0 7pt; padding:0 0 4pt; border:0; border-bottom:1px solid #333; }
h3 { font-size:10.6pt; line-height:1.35; margin:9pt 0 3pt; border:0; }
table { width:100%; border-collapse:collapse; font-size:9.7pt; margin:5pt 0 10pt; }
th,td { text-align:left; vertical-align:top; padding:5pt 7pt; border:0; border-bottom:1px solid #d1d5da; background:white; }
th { background:#f0f2f4; font-weight:700; }
td ul { margin:0; padding-left:12pt; }
.resume-sheet { width:100%; }
.meta { color:#555; font-size:9.2pt; }
.project-table td:first-child { width:22%; font-weight:600; background:#f6f7f8; }
.project-table td { padding:5pt 7pt; }

body { font-family:"Apple SD Gothic Neo","Malgun Gothic",sans-serif; font-size:10.3pt; line-height:1.5; }
h1 { font-size:29pt; line-height:1.15; margin:0 0 7pt; border:0; padding:0; }
h2 { color:#233d52; font-size:12.4pt; margin-top:15pt; }
.resume-top { display:flex; justify-content:space-between; gap:18pt; align-items:flex-start; margin-bottom:17pt; }
.resume-title { font-size:12pt; font-weight:600; color:#404b56; }
.contacts { font-size:9.2pt; line-height:1.65; text-align:right; }
.intro-list { margin-top:5pt; }
.skill-table td:first-child { width:26%; font-weight:600; }
.career-table { font-size:9.5pt; }
.career-table th:nth-child(1) { width:21%; }
.career-table th:nth-child(2) { width:29%; }
.section-start { margin-top:0; }
